ReplacementContent:
"                            <input 
                              type="number" 
                              value={item.quantity}
                              min="1"
                              onChange={(e) => updateCartItemQtyAbsolute(item.id, e.target.value)}
                              onFocus={(e) => e.target.select()}
                              onKeyDown={(e) => { if (e.key === 'Enter') e.target.blur(); }}
                              autoFocus={item.id === lastAddedItemId}
                              className={`font-bold w-10 text-center rounded outline-none border-0 py-0.5 select-all focus:ring-1 focus:ring-[#10ac84] [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none ${isDark ? 'bg-gray-900 text-gray-100 focus:bg-black' : 'bg-slate-100 text-slate-800 focus:bg-white'}`}
                            />"

